create or replace function public.cuenta_json(a public.cuentas_por_cobrar)returns jsonb language sql stable security definer set search_path = '' as $$select jsonb_build_object('id',a.id,'planId',p.id,'patientId',a.paciente_id,'patientName',concat_ws(' ',x.nombres,x.apellido_paterno,x.apellido_materno),'planCode',p.codigo,'totalAmount',a.monto_total,'paidAmount',a.monto_pagado,'balance',a.saldo,'status',a.estado,'dueDate',a.fecha_vencimiento,'updatedAt',a.actualizado_en,'version',a.version)from public.planes_tratamiento p join public.pacientes x on x.id=a.paciente_id where p.id=a.plan_id $$;
create or replace function public.caja_json(s public.sesiones_caja)returns jsonb language sql immutable set search_path = '' as $$select jsonb_build_object('id',s.id,'openedBy',s.abierta_por,'openedAt',s.abierta_en,'openingAmount',s.monto_apertura,'status',s.estado,'closedBy',s.cerrada_por,'closedAt',s.cerrada_en,'expectedAmount',s.monto_esperado,'countedAmount',s.monto_contado,'difference',s.diferencia,'closingObservation',s.observacion_cierre,'version',s.version) $$;
create or replace function public.pago_json(p public.pagos)returns jsonb language sql stable security definer set search_path = '' as $$select jsonb_build_object('id',p.id,'accountId',p.cuenta_id,'patientId',p.paciente_id,'patientName',x.nombres||' '||x.apellido_paterno,'planId',p.plan_id,'planCode',t.codigo,'cashSessionId',p.sesion_caja_id,'paymentMethodId',m.id,'paymentMethod',m.nombre,'amount',p.monto,'reference',p.referencia,'receiptNumber',p.numero_constancia,'status',p.estado,'registeredAt',p.registrado_en)from public.pacientes x join public.planes_tratamiento t on t.id=p.plan_id join public.metodos_pago m on m.id=p.metodo_pago_id where x.id=p.paciente_id $$;
create or replace function public.gasto_json(g public.gastos)returns jsonb language sql stable security definer set search_path = '' as $$select jsonb_build_object('id',g.id,'cashSessionId',g.sesion_caja_id,'category',g.categoria,'description',g.descripcion,'provider',g.proveedor,'documentReference',g.documento_referencia,'paymentMethodId',m.id,'paymentMethod',m.nombre,'amount',g.monto,'status',g.estado,'registeredAt',g.registrado_en)from public.metodos_pago m where m.id=g.metodo_pago_id $$;
create or replace function public.validar_finanza()returns bigint language plpgsql stable security definer set search_path = '' as $$declare actor bigint:=public.current_app_user_id();begin if actor is null or not public.has_permission('FINANZA_ESCRIBIR')then raise exception using errcode='42501',message='No autorizado para operar caja';end if;return actor;end $$;

create or replace function public.listar_cuentas(estado_filtro text default null,paciente_id bigint default null)returns jsonb language plpgsql stable security definer set search_path = '' as $$declare result jsonb;begin if not public.has_permission('FINANZA_LEER')then raise exception using errcode='42501',message='No autorizado para consultar finanzas';end if;select coalesce(jsonb_agg(public.cuenta_json(a)order by a.actualizado_en desc),'[]'::jsonb)into result from public.cuentas_por_cobrar a where(listar_cuentas.estado_filtro is null or a.estado=listar_cuentas.estado_filtro)and(listar_cuentas.paciente_id is null or a.paciente_id=listar_cuentas.paciente_id);return result;end $$;
create or replace function public.caja_actual()returns jsonb language plpgsql stable security definer set search_path = '' as $$declare result jsonb;begin if not public.has_permission('FINANZA_LEER')then raise exception using errcode='42501',message='No autorizado para consultar caja';end if;select public.caja_json(s)into result from public.sesiones_caja s where s.estado='ABIERTA'order by s.abierta_en desc limit 1;return result;end $$;
create or replace function public.abrir_caja(monto numeric)returns jsonb language plpgsql security definer set search_path = '' as $$declare actor bigint:=public.validar_finanza();item public.sesiones_caja;begin if monto<0 then raise exception using errcode='P0001',message='Monto de apertura inválido';end if;insert into public.sesiones_caja(abierta_por,monto_apertura)values(actor,monto)returning*into item;perform public.registrar_auditoria('ABRIR_CAJA','FINANZAS',item.id::text,'Apertura '||monto);return public.caja_json(item);exception when unique_violation then raise exception using errcode='P0001',message='Ya existe una caja abierta';end $$;
create or replace function public.cerrar_caja(caja_id bigint,monto_contado numeric,observacion text,version_actual bigint,confirmacion boolean)returns jsonb language plpgsql security definer set search_path = '' as $$declare actor bigint:=public.validar_finanza();item public.sesiones_caja;cash_id bigint;expected numeric(12,2);begin if confirmacion is not true then raise exception using errcode='P0001',message='Confirme el cierre de caja';end if;select*into item from public.sesiones_caja where id=caja_id for update;if not found then raise exception using errcode='P0001',message='Caja no encontrada';end if;if item.estado<>'ABIERTA'then raise exception using errcode='P0001',message='La caja ya está cerrada';end if;if item.version<>version_actual then raise exception using errcode='P0001',message='La caja fue modificada';end if;select id into cash_id from public.metodos_pago where codigo='EFECTIVO';select item.monto_apertura+coalesce(sum(case when tipo='INGRESO'then monto else -monto end),0)into expected from public.movimientos_caja where sesion_caja_id=caja_id and metodo_pago_id=cash_id;update public.sesiones_caja set estado='CERRADA',cerrada_por=actor,cerrada_en=now(),monto_esperado=expected,monto_contado=monto_contado,diferencia=monto_contado-expected,observacion_cierre=nullif(btrim(observacion),''),version=version+1 where id=caja_id returning*into item;perform public.registrar_auditoria('CERRAR_CAJA','FINANZAS',caja_id::text,'Diferencia '||item.diferencia);return public.caja_json(item);end $$;
create or replace function public.registrar_pago(datos jsonb)returns jsonb language plpgsql security definer set search_path = '' as $$declare actor bigint:=public.validar_finanza();cash public.sesiones_caja;account public.cuentas_por_cobrar;method public.metodos_pago;item public.pagos;amount numeric:=(datos->>'amount')::numeric;begin select*into cash from public.sesiones_caja where estado='ABIERTA'for update;if not found then raise exception using errcode='P0001',message='Abra la caja antes de registrar operaciones';end if;select*into account from public.cuentas_por_cobrar where id=(datos->>'accountId')::bigint for update;if not found then raise exception using errcode='P0001',message='Cuenta por cobrar no encontrada';end if;if account.estado in('PAGADA','ANULADA')or amount>account.saldo then raise exception using errcode='P0001',message='El pago supera el saldo pendiente o la cuenta no admite pagos';end if;select*into method from public.metodos_pago where id=(datos->>'paymentMethodId')::bigint and activo;if not found then raise exception using errcode='P0001',message='Método de pago no encontrado';end if;if method.requiere_referencia and nullif(btrim(datos->>'reference'),'')is null then raise exception using errcode='P0001',message='El método de pago requiere referencia';end if;insert into public.pagos(cuenta_id,paciente_id,plan_id,sesion_caja_id,metodo_pago_id,monto,referencia,numero_constancia,registrado_por,confirmado_por)values(account.id,account.paciente_id,account.plan_id,cash.id,method.id,amount,nullif(btrim(datos->>'reference'),''),'REC-'||extract(year from current_date)::text||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8)),actor,actor)returning*into item;update public.cuentas_por_cobrar set monto_pagado=monto_pagado+amount,saldo=saldo-amount,estado=case when saldo-amount=0 then'PAGADA'else'PARCIAL'end,actualizado_en=now(),version=version+1 where id=account.id;insert into public.movimientos_caja(sesion_caja_id,tipo,categoria,origen,origen_id,metodo_pago_id,monto,descripcion,creado_por)values(cash.id,'INGRESO','COBRO_TRATAMIENTO','PAGO',item.id,method.id,amount,'Pago '||item.numero_constancia,actor);perform public.registrar_auditoria('REGISTRAR_PAGO','FINANZAS',item.id::text,item.numero_constancia);return public.pago_json(item);end $$;
create or replace function public.registrar_gasto(datos jsonb)returns jsonb language plpgsql security definer set search_path = '' as $$declare actor bigint:=public.validar_finanza();cash public.sesiones_caja;method public.metodos_pago;item public.gastos;begin select*into cash from public.sesiones_caja where estado='ABIERTA'for update;if not found then raise exception using errcode='P0001',message='Abra la caja antes de registrar operaciones';end if;select*into method from public.metodos_pago where id=(datos->>'paymentMethodId')::bigint and activo;if not found then raise exception using errcode='P0001',message='Método de pago no encontrado';end if;insert into public.gastos(sesion_caja_id,categoria,descripcion,proveedor,documento_referencia,metodo_pago_id,monto,registrado_por,confirmado_por)values(cash.id,btrim(datos->>'category'),btrim(datos->>'description'),nullif(btrim(datos->>'provider'),''),nullif(btrim(datos->>'documentReference'),''),method.id,(datos->>'amount')::numeric,actor,actor)returning*into item;insert into public.movimientos_caja(sesion_caja_id,tipo,categoria,origen,origen_id,metodo_pago_id,monto,descripcion,creado_por)values(cash.id,'EGRESO',item.categoria,'GASTO',item.id,method.id,item.monto,item.descripcion,actor);perform public.registrar_auditoria('REGISTRAR_GASTO','FINANZAS',item.id::text,item.categoria);return public.gasto_json(item);end $$;
create or replace function public.listar_pagos(desde timestamptz,hasta timestamptz)returns jsonb language plpgsql stable security definer set search_path = '' as $$declare result jsonb;begin if not public.has_permission('FINANZA_LEER')then raise exception using errcode='42501',message='No autorizado';end if;if hasta<=desde or hasta-desde>interval'367 days'then raise exception using errcode='P0001',message='Rango financiero inválido';end if;select coalesce(jsonb_agg(public.pago_json(p)order by p.registrado_en desc),'[]'::jsonb)into result from public.pagos p where p.registrado_en between desde and hasta;return result;end $$;
create or replace function public.listar_gastos(desde timestamptz,hasta timestamptz)returns jsonb language plpgsql stable security definer set search_path = '' as $$declare result jsonb;begin if not public.has_permission('FINANZA_LEER')then raise exception using errcode='42501',message='No autorizado';end if;if hasta<=desde or hasta-desde>interval'367 days'then raise exception using errcode='P0001',message='Rango financiero inválido';end if;select coalesce(jsonb_agg(public.gasto_json(g)order by g.registrado_en desc),'[]'::jsonb)into result from public.gastos g where g.registrado_en between desde and hasta;return result;end $$;
create or replace function public.resumen_finanzas(desde timestamptz,hasta timestamptz)returns jsonb language plpgsql stable security definer set search_path = '' as $$declare income numeric;expense numeric;receivable numeric;cash numeric;cash_id bigint;result jsonb;begin if not public.has_permission('FINANZA_LEER')then raise exception using errcode='42501',message='No autorizado';end if;if hasta<=desde or hasta-desde>interval'367 days'then raise exception using errcode='P0001',message='Rango financiero inválido';end if;select id into cash_id from public.metodos_pago where codigo='EFECTIVO';select coalesce(sum(monto)filter(where tipo='INGRESO'),0),coalesce(sum(monto)filter(where tipo='EGRESO'),0),coalesce(sum(monto)filter(where tipo='INGRESO'and metodo_pago_id=cash_id),0)into income,expense,cash from public.movimientos_caja where creado_en between desde and hasta;select coalesce(sum(saldo),0)into receivable from public.cuentas_por_cobrar where estado<>'ANULADA';select jsonb_build_object('income',income,'expenses',expense,'net',income-expense,'receivable',receivable,'cashIncome',cash,'digitalIncome',income-cash,'paymentsCount',(select count(*)from public.pagos where registrado_en between desde and hasta),'expensesCount',(select count(*)from public.gastos where registrado_en between desde and hasta),'recentMovements',coalesce((select jsonb_agg(x.data)from(select jsonb_build_object('id',m.id,'cashSessionId',m.sesion_caja_id,'type',m.tipo,'category',m.categoria,'source',m.origen,'sourceId',m.origen_id,'paymentMethod',pm.nombre,'amount',m.monto,'description',m.descripcion,'createdAt',m.creado_en)data from public.movimientos_caja m left join public.metodos_pago pm on pm.id=m.metodo_pago_id where m.creado_en between desde and hasta order by m.creado_en desc limit 20)x),'[]'::jsonb))into result;return result;end $$;

do $$declare r record;begin for r in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname in('cuenta_json','caja_json','pago_json','gasto_json','validar_finanza','listar_cuentas','caja_actual','abrir_caja','cerrar_caja','registrar_pago','registrar_gasto','listar_pagos','listar_gastos','resumen_finanzas')loop execute format('revoke all on function %s from public',r.signature);end loop;end $$;
grant execute on function public.listar_cuentas(text,bigint),public.caja_actual(),public.abrir_caja(numeric),public.cerrar_caja(bigint,numeric,text,bigint,boolean),public.registrar_pago(jsonb),public.registrar_gasto(jsonb),public.listar_pagos(timestamptz,timestamptz),public.listar_gastos(timestamptz,timestamptz),public.resumen_finanzas(timestamptz,timestamptz)to authenticated;
